<?php $page_title='Daftar';include 'partials/header.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']);$email=trim($_POST['email']);$pw=$_POST['password'];if(strlen($pw)<6)$err='Password minimal 6 karakter.';else{$hash=password_hash($pw,PASSWORD_DEFAULT);$st=$conn->prepare('INSERT INTO users(name,email,password) VALUES(?,?,?)');$st->bind_param('sss',$name,$email,$hash);if($st->execute()){header('Location: login.php?registered=1');exit;}else $err='Email sudah terdaftar atau data tidak valid.';}}?><section class="auth panel"><h2>Buat Akun</h2><?php if($err):?><div class="alert"><?=$err?></div><?php endif;?><form method="post"><div class="form-group"><label>Nama lengkap</label><input class="input" name="name" required></div><div class="form-group"><label>Email</label><input class="input" type="email" name="email" required></div><div class="form-group"><label>Password</label><input class="input" type="password" name="password" required></div><button class="btn" style="width:100%">Daftar</button></form><p class="muted" style="text-align:center">Sudah punya akun? <a href="login.php">Masuk</a></p></section><?php include 'partials/footer.php';?>
